package com.arenashowdown.parkour.command;

import com.arenashowdown.parkour.ParkourAdapter;
import com.arenashowdown.parkour.arena.*;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.Plugin;
import java.io.IOException;
import java.util.*;

public final class ParkourCommand implements CommandExecutor,TabCompleter {
    private final Plugin plugin;private final ArenaStore store;private final ParkourAdapter adapter;private final Map<UUID,Location>pos1=new HashMap<>(),pos2=new HashMap<>();
    public ParkourCommand(Plugin plugin,ArenaStore store,ParkourAdapter adapter){this.plugin=plugin;this.store=store;this.adapter=adapter;}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[]a){if(!(sender instanceof Player p)){sender.sendMessage("Comando exclusivo para jogador");return true;}if(!p.hasPermission("arena.parkour.admin")){error(p,"Sem permissao: arena.parkour.admin");return true;}try{if(a.length==0||a[0].equalsIgnoreCase("help")){help(p);return true;}switch(a[0].toLowerCase(Locale.ROOT)){case "create"->{need(a,2,"/parkour create <nome>");if(store.get(a[1]).isPresent())throw new IllegalStateException("Arena ja existe");ParkourArena ar=new ParkourArena(a[1],p.getWorld().getName(),point(p.getLocation()),List.of(),List.of(),null,null,plugin.getConfig().getLong("default-time-limit-seconds",300),plugin.getConfig().getDouble("default-fall-height",50),Map.of());store.put(ar);ok(p,"Arena criada em memoria; configure e use /parkour save "+a[1]);}case "pos1"->{pos1.put(p.getUniqueId(),p.getLocation().getBlock().getLocation());ok(p,"Ponto 1 selecionado.");}case "pos2"->{pos2.put(p.getUniqueId(),p.getLocation().getBlock().getLocation());ok(p,"Ponto 2 selecionado.");}case "setstart"->{ParkourArena x=get(a,1);put(copy(x,point(p.getLocation()),x.spawns(),x.checkpoints(),x.finish(),x.lobby(),x.fallHeight()));ok(p,"Largada definida.");}case "addspawn"->{ParkourArena x=get(a,1);List<ArenaPoint>list=new ArrayList<>(x.spawns());list.add(point(p.getLocation()));put(copy(x,x.start(),list,x.checkpoints(),x.finish(),x.lobby(),x.fallHeight()));ok(p,"Spawn "+list.size()+" adicionado.");}case "addcheckpoint"->{ParkourArena x=get(a,1);List<BlockRegion>list=new ArrayList<>(x.checkpoints());list.add(selection(p));put(copy(x,x.start(),x.spawns(),list,x.finish(),x.lobby(),x.fallHeight()));ok(p,"Checkpoint "+list.size()+" adicionado.");}case "setfinish"->{ParkourArena x=get(a,1);put(copy(x,x.start(),x.spawns(),x.checkpoints(),selection(p),x.lobby(),x.fallHeight()));ok(p,"Chegada definida.");}case "setfallheight"->{need(a,3,"/parkour setfallheight <arena> <altura>");ParkourArena x=required(a[1]);put(copy(x,x.start(),x.spawns(),x.checkpoints(),x.finish(),x.lobby(),Double.parseDouble(a[2])));ok(p,"Altura de queda definida.");}case "setlobby"->{ParkourArena x=get(a,1);put(copy(x,x.start(),x.spawns(),x.checkpoints(),x.finish(),point(p.getLocation()),x.fallHeight()));ok(p,"Lobby definido.");}case "validate"->{ParkourArena x=get(a,1);List<String>errors=x.validate();if(errors.isEmpty())ok(p,"Arena valida: "+x.spawns().size()+" spawns, "+x.checkpoints().size()+" checkpoints");else error(p,"Arena incompleta: "+String.join(", ",errors));}case "save"->{ParkourArena x=get(a,1);store.save(x);ok(p,"Arena salva em YAML: "+x.name());}case "test"->{ParkourArena x=get(a,1);List<String>errors=x.validate();if(!errors.isEmpty())throw new IllegalStateException("Arena incompleta: "+String.join(", ",errors));p.setGameMode(GameMode.ADVENTURE);p.teleport(location(x.spawns().getFirst()));ok(p,"Teste local iniciado; este comando nao pontua.");}case "buildtest"->{need(a,2,"/parkour buildtest <nome>");buildTest(p,a[1]);}default->help(p);}}catch(Exception e){error(p,e.getMessage());}return true;}
    private void buildTest(Player p,String name)throws IOException{World world=Bukkit.getWorld("parkour_test");if(world==null)world=Bukkit.createWorld(new WorldCreator("parkour_test").type(WorldType.FLAT));if(world==null)throw new IllegalStateException("Nao foi possivel criar parkour_test");int y=70;for(int x=-8;x<=68;x++)for(int z=-10;z<=10;z++)world.getBlockAt(x,y-6,z).setType(Material.BLACK_CONCRETE);List<ArenaPoint>spawns=List.of(new ArenaPoint(world.getName(),0.5,y,0.5,-90,0),new ArenaPoint(world.getName(),0.5,y,2.5,-90,0));for(int x=-2;x<=4;x++)for(int z=-2;z<=4;z++)world.getBlockAt(x,y-1,z).setType((x+z)%2==0?Material.RED_CONCRETE:Material.BLACK_CONCRETE);int[][]platforms={{8,0},{14,3},{20,-2},{26,2},{32,-3},{38,0},{44,3},{50,-2},{56,1},{62,0}};List<BlockRegion>checks=new ArrayList<>();for(int i=0;i<platforms.length;i++){int x=platforms[i][0],z=platforms[i][1];Material m=i%2==0?Material.GOLD_BLOCK:Material.QUARTZ_BLOCK;for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)world.getBlockAt(x+dx,y-1,z+dz).setType(m);if(i%2==1)checks.add(BlockRegion.between(world.getName(),x-1,y,z-1,x+1,y+2,z+1));}for(int x=65;x<=69;x++)for(int z=-3;z<=3;z++)world.getBlockAt(x,y-1,z).setType(Material.EMERALD_BLOCK);for(int x=72;x<=80;x++)for(int z=-5;z<=5;z++)world.getBlockAt(x,y+5,z).setType(Material.SMOOTH_QUARTZ);ParkourArena arena=new ParkourArena(name,world.getName(),spawns.getFirst(),spawns,checks,BlockRegion.between(world.getName(),65,y,-3,69,y+3,3),new ArenaPoint(world.getName(),75.5,y+6,0.5,90,0),300,y-5,Map.of("theme","casino","adventure",true));store.save(arena);p.teleport(location(spawns.getFirst()));ok(p,"Pista reproduzivel criada em parkour_test e arena salva: "+name);}
    private ParkourArena get(String[]a,int index){need(a,index+1,"Arena obrigatoria");return required(a[index]);}private ParkourArena required(String name){return store.get(name).orElseThrow(()->new IllegalArgumentException("Arena nao encontrada: "+name));}private void put(ParkourArena a){store.put(a);}private ParkourArena copy(ParkourArena x,ArenaPoint start,List<ArenaPoint>spawns,List<BlockRegion>checks,BlockRegion finish,ArenaPoint lobby,double fall){return new ParkourArena(x.name(),x.world(),start,spawns,checks,finish,lobby,x.timeLimitSeconds(),fall,x.rules());}private BlockRegion selection(Player p){Location a=pos1.get(p.getUniqueId()),b=pos2.get(p.getUniqueId());if(a==null||b==null)throw new IllegalStateException("Use /parkour pos1 e /parkour pos2");if(!a.getWorld().equals(b.getWorld()))throw new IllegalStateException("Os pontos devem estar no mesmo mundo");return BlockRegion.between(a.getWorld().getName(),a.getBlockX(),a.getBlockY(),a.getBlockZ(),b.getBlockX(),b.getBlockY(),b.getBlockZ());}private ArenaPoint point(Location l){return new ArenaPoint(l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());}private Location location(ArenaPoint p){World w=Bukkit.getWorld(p.world());if(w==null)throw new IllegalStateException("Mundo nao carregado");return new Location(w,p.x(),p.y(),p.z(),p.yaw(),p.pitch());}private void need(String[]a,int n,String usage){if(a.length<n)throw new IllegalArgumentException("Uso: "+usage);}private void help(Player p){p.sendMessage(Component.text("/parkour create|pos1|pos2|setstart|addspawn|addcheckpoint|setfinish|setfallheight|setlobby|validate|save|test|buildtest",NamedTextColor.GOLD));}private void ok(Player p,String m){p.sendMessage(Component.text(m,NamedTextColor.GREEN));}private void error(Player p,String m){p.sendMessage(Component.text(m==null?"Erro interno":m,NamedTextColor.RED));}
    @Override public List<String>onTabComplete(CommandSender s,Command c,String alias,String[]a){return a.length==1?List.of("create","pos1","pos2","setstart","addspawn","addcheckpoint","setfinish","setfallheight","setlobby","validate","save","test","buildtest").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList():List.of();}
}
